import { fileURLToPath } from "node:url";
import { migrate } from "drizzle-orm/libsql/migrator";
import type { Database } from "./index";

/** SQL migrations generated by `drizzle-kit generate` (committed). */
export const migrationsFolder = fileURLToPath(new URL("./migrations", import.meta.url));

/** Apply pending migrations (forward only). Safe to call more than once. */
export async function runMigrations(db: Database, databaseUrl: string): Promise<void> {
	if (databaseUrl.startsWith("file:") && !databaseUrl.includes(":memory:")) {
		// WAL lets readers proceed while a sync batch is being written.
		await db.$client.execute("PRAGMA journal_mode = WAL");
	}
	await migrate(db, { migrationsFolder });
}
